public class UserMentionProvider : IMentionDataProvider
{
    private readonly IUserService _userService;

    public UserMentionProvider(IUserService userService)
    {
        _userService = userService;
    }

    public async Task<IReadOnlyList<IMentionUser>> GetUsersAsync(
        string searchText, CancellationToken ct = default)
    {
        var users = await _userService.SearchAsync(searchText, 10, ct);
        return users.Select(u => new MentionUser
        {
            Id = u.Id,
            Name = u.FullName,
            AvatarUrl = u.AvatarUrl
        }).ToList();
    }
}
